def pos(name='obj_main'):
    return d.xpos[m.body(name).id].copy()

def pose(arm='right'):
    i=m.site('gripper0_'+arm+'_grip_site').id
    return d.site_xpos[i].copy(),d.site_xmat[i].reshape(3,3).copy()

def move(p=None,R=None,hand=None,n=50,arm='right'):
    a=s.targets.copy(); k=0 if arm=='right' else 6; h=12 if arm=='right' else 18
    end=a.copy()
    if p is not None: end[k:k+3]=Rb.T@(np.array(p)-pb)
    if R is not None: end[k+3:k+6]=Rot.from_matrix(Rb.T@R).as_rotvec()
    if hand is not None: end[h:h+6]=hand
    rots=Slerp([0,1],Rot.from_rotvec([a[k+3:k+6],end[k+3:k+6]]))
    for t in range(1,n+1):
        f=t/n; row=a+(end-a)*f
        row[k+3:k+6]=rots([f]).as_rotvec()[0]
        s.step(row)
    return report()

def hold(n=20):
    for _ in range(n): s.step(s.targets)
    return report()

